        {
          "id": "header_title",
          "component": "Text",
          "variant": "h2",
          "text": "Tokyo Family Itinerary: Anime, Tech & Museums (June 10-15, 2025)"
        },
        {
          "id": "assumptions_card",
          "component": "Card",
          "child": "assumptions_column"
        },
        {
          "id": "assumptions_column",
