            "summary_text"
          ]
        },
        {
          "id": "summary_title",
          "component": "Text",
          "variant": "h3",
          "text": "Summary"
        },
        {
          "id": "summary_text",
          "component": "Text",
          "text": "This 5-day itinerary for a family of four (children aged 8 and 10) visiting Tokyo from June 10-15, 2025, focuses on a blend of anime culture, interactive technology experiences, and engaging kid-friendly museums. Each day is designed to explore a specific neighborhood, minimizing travel time and maximizing enjoyment."
        },
        {
          "id": "itinerary_tabs",
          "component": "Tabs",
          "tabs": [
            {
              "title": "Day 1: Shinjuku",
              "child": "day1_content"
            },
            {
              "title": "Day 2: Mitaka & Shibuya",
              "child": "day2_content"
            },
            {
              "title": "Day 3: Akihabara & Ueno",
              "child": "day3_content"
            },
            {
              "title": "Day 4: Odaiba",
              "child": "day4_content"
            },
            {
              "title": "Day 5: Asakusa",
              "child": "day5_content"
            }
          ]
        },
        {
          "id": "day1_content",
          "component": "Column",
          "children": [
            "day1_image",
            "day1_details_title",
            "day1_details_text",
            "day1_activities_title",
            "day1_activities_list",
            "day1_attractions_title",
            "day1_attractions_list",
            "day1_cost_title",
            "day1_cost_list"
          ]
        },
        {
          "id": "day1_image",
          "component": "Image",
          "variant": "mediumFeature",
          "url": "/shibuya_crossing.jpg"
        },
        {
          "id": "day1_details_title",
          "component": "Text",
          "variant": "h4",
          "text": "Day 1: Arrival & Shinjuku - City Views and Green Spaces"
        },
        {
          "id": "day1_details_text",
          "component": "Text",
          "text": "Date: 2025-06-10 (Tuesday)\nNeighborhood: Shinjuku\nTheme: Cityscapes, Relaxed Exploration, Modern Tokyo"
        },
        {
          "id": "day1_activities_title",
          "component": "Text",
          "variant": "h4",
          "text": "Activities"
        },
        {
          "id": "day1_activities_list",
          "component": "Column",
          "children": [
            "day1_activity1",
            "day1_activity2",
            "day1_activity3"
          ]
        },
        {
          "id": "day1_activity1",
          "component": "Text",
          "text": "• Morning/Afternoon: Arrive at Narita (NRT) or Haneda (HND) Airport, transfer to your hotel, check-in, and settle."
        },
        {
          "id": "day1_activity2",
          "component": "Text",
          "text": "• Afternoon: Visit Shinjuku Gyoen National Garden. A beautiful oasis perfect for unwinding after travel."
        },
        {
          "id": "day1_activity3",
          "component": "Text",
          "text": "• Evening: Ascend to the Tokyo Metropolitan Government Building Observation Decks for free panoramic city views. Explore Shinjuku's bustling streets and enjoy dinner."
        },
        {
          "id": "day1_attractions_title",
          "component": "Text",
          "variant": "h4",
          "text": "Key Attractions"
        },
        {
          "id": "day1_attractions_list",
          "component": "Column",
          "children": [
            "day1_attraction1",
            "day1_attraction2"
          ]
        },
        {
          "id": "day1_attraction1",
          "component": "Text",
          "text": "• Shinjuku Gyoen National Garden: A large park with traditional Japanese, French, and English landscape gardens."
        },
        {
          "id": "day1_attraction2",
          "component": "Text",
          "text": "• Tokyo Metropolitan Government Building: Free observation decks offering stunning views of Tokyo, including Mount Fuji on clear days."
        },
        {
          "id": "day1_cost_title",
          "component": "Text",
          "variant": "h4",
          "text": "Estimated Daily Cost (Family of 4): USD 320"
        },
        {
          "id": "day1_cost_list",
          "component": "Column",
          "children": [
            "day1_cost1",
            "day1_cost2",
            "day1_cost3"
          ]
        },
        {
          "id": "day1_cost1",
          "component": "Text",
          "text": "• Transportation (trains/subway): USD 50"
        },
        {
          "id": "day1_cost2",
          "component": "Text",
          "text": "• Meals (lunch, dinner, snacks): USD 200"
        },
        {
          "id": "day1_cost3",
          "component": "Text",
          "text": "• Activities (garden entry, observation deck free): USD 70"
        },
        {
          "id": "day2_content",
          "component": "Column",
          "children": [
            "day2_image",
            "day2_details_title",
            "day2_details_text",
            "day2_activities_title",
            "day2_activities_list",
            "day2_attractions_title",
            "day2_attractions_list",
            "day2_cost_title",
            "day2_cost_list"
          ]
        },
        {
          "id": "day2_image",
          "component": "Image",
          "variant": "mediumFeature",
          "url": "/ghibli_museum.jpg"
        },
        {
          "id": "day2_details_title",
          "component": "Text",
          "variant": "h4",
          "text": "Day 2: Mitaka & Shibuya - Ghibli Magic and Iconic Crossing"
        },
        {
          "id": "day2_details_text",
          "component": "Text",
          "text": "Date: 2025-06-11 (Wednesday)\nNeighborhood: Mitaka, Shibuya\nTheme: Anime Immersion, Pop Culture Icon"
        },
        {
          "id": "day2_activities_title",
          "component": "Text",
          "variant": "h4",
          "text": "Activities"
        },
        {
          "id": "day2_activities_list",
          "component": "Column",
          "children": [
            "day2_activity1",
            "day2_activity2",
            "day2_activity3"
          ]
        },
        {
          "id": "day2_activity1",
          "component": "Text",
          "text": "• Morning: Journey to Mitaka for a pre-booked visit to the Ghibli Museum. Immerse yourselves in the enchanting world of Studio Ghibli."
        },
        {
          "id": "day2_activity2",
          "component": "Text",
          "text": "• Afternoon: Explore Inokashira Park, adjacent to the museum, which features a zoo and boating pond. Travel to Shibuya."
        },
        {
          "id": "day2_activity3",
          "component": "Text",
          "text": "• Evening: Experience the famous Shibuya Crossing, visit the Hachiko statue, and explore Shibuya's shops and restaurants."
        },
        {
          "id": "day2_attractions_title",
          "component": "Text",
          "variant": "h4",
          "text": "Key Attractions"
        },
        {
          "id": "day2_attractions_list",
          "component": "Column",
          "children": [
            "day2_attraction1",
            "day2_attraction2",
            "day2_attraction3"
          ]
        },
        {
          "id": "day2_attraction1",
          "component": "Text",
          "text": "• Ghibli Museum (Mitaka): A whimsical museum dedicated to the works of Studio Ghibli. IMPORTANT: Tickets must be purchased months in advance."
        },
        {
          "id": "day2_attraction2",
          "component": "Text",
          "text": "• Inokashira Park: A large, family-friendly park with a zoo, an aquarium, and paddle boats."
        },
        {
          "id": "day2_attraction3",
          "component": "Text",
          "text": "• Shibuya Crossing: One of the world's busiest intersections, an iconic Tokyo experience."
        },
        {
          "id": "day2_cost_title",
          "component": "Text",
          "variant": "h4",
          "text": "Estimated Daily Cost (Family of 4): USD 360"
        },
        {
          "id": "day2_cost_list",
          "component": "Column",
          "children": [
            "day2_cost1",
            "day2_cost2",
            "day2_cost3"
          ]
        },
        {
          "id": "day2_cost1",
          "component": "Text",
          "text": "• Transportation: USD 60"
        },
        {
          "id": "day2_cost2",
          "component": "Text",
          "text": "• Meals: USD 220"
        },
        {
          "id": "day2_cost3",
          "component": "Text",
          "text": "• Activities (Ghibli Museum, park entry): USD 80"
        },
        {
          "id": "day3_content",
          "component": "Column",
          "children": [
            "day3_image",
            "day3_details_title",
