            "day3_attractions_list",
            "day3_cost_title",
            "day3_cost_list"
          ]
        },
        {
          "id": "day3_image",
          "component": "Image",
          "variant": "mediumFeature",
          "url": "/akihabara_electric_town.jpg"
        },
        {
          "id": "day3_details_title",
          "component": "Text",
          "variant": "h4",
          "text": "Day 3: Akihabara & Ueno - Anime, Tech, and Science"
        },
        {
          "id": "day3_details_text",
          "component": "Text",
          "text": "Date: 2025-06-12 (Thursday)\nNeighborhood: Akihabara, Ueno\nTheme: Anime Hub, Electronics, Kid-friendly Museums"
        },
        {
          "id": "day3_activities_title",
          "component": "Text",
          "variant": "h4",
          "text": "Activities"
        },
        {
          "id": "day3_activities_list",
          "component": "Column",
          "children": [
            "day3_activity1",
            "day3_activity2",
            "day3_activity3"
          ]
        },
        {
          "id": "day3_activity1",
          "component": "Text",
          "text": "• Morning: Dive into Akihabara Electric Town. Explore anime and manga shops, electronics stores, and themed cafes. Kids might enjoy the arcades."
        },
        {
          "id": "day3_activity2",
          "component": "Text",
          "text": "• Afternoon: Head to Ueno Park. Choose one kid-friendly museum: the National Museum of Nature and Science (interactive exhibits) or the Ueno Zoo."
        },
        {
          "id": "day3_activity3",
          "component": "Text",
          "text": "• Evening: Enjoy dinner in Ueno or Akihabara, perhaps trying a themed restaurant in Akihabara."
        },
        {
          "id": "day3_attractions_title",
          "component": "Text",
          "variant": "h4",
          "text": "Key Attractions"
        },
        {
          "id": "day3_attractions_list",
          "component": "Column",
          "children": [
            "day3_attraction1",
            "day3_attraction2",
            "day3_attraction3"
          ]
        },
        {
          "id": "day3_attraction1",
          "component": "Text",
          "text": "• Akihabara Electric Town: The center for Japanese anime, manga, video games, and electronics."
        },
        {
          "id": "day3_attraction2",
          "component": "Text",
          "text": "• National Museum of Nature and Science (Ueno): Features engaging exhibits on science and natural history, including dinosaurs."
        },
        {
          "id": "day3_attraction3",
          "component": "Text",
          "text": "• Ueno Zoo: Home to pandas and various other animals, a popular choice for families."
        },
        {
          "id": "day3_cost_title",
          "component": "Text",
          "variant": "h4",
          "text": "Estimated Daily Cost (Family of 4): USD 380"
        },
        {
          "id": "day3_cost_list",
          "component": "Column",
          "children": [
            "day3_cost1",
            "day3_cost2",
            "day3_cost3"
          ]
        },
        {
          "id": "day3_cost1",
          "component": "Text",
          "text": "• Transportation: USD 50"
        },
        {
          "id": "day3_cost2",
          "component": "Text",
          "text": "• Meals: USD 230"
        },
        {
          "id": "day3_cost3",
          "component": "Text",
          "text": "• Activities (museum/zoo entry, arcades): USD 100"
        },
        {
          "id": "day4_content",
          "component": "Column",
          "children": [
            "day4_image",
            "day4_details_title",
            "day4_details_text",
            "day4_activities_title",
            "day4_activities_list",
